  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "After i.v. administration in mice, brain concentrations of Merck-3 were below the limit of detection while plasma concentrations were ~1.3 µM, and the compound was identified as a P-gp substrate, indicating poor brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "In rats, brain uptake of 14C-MBDA was only 0.06 ± 0.01% of the injected dose per gram of tissue, consistent with poor CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Tarenflurbil showed insufficient brain penetration in a Phase I trial and animal studies, with maximal brain concentrations around 1-2 µM, approximately 100-fold below concentrations needed for target engagement.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved experimental records consistently indicate poor or impermeable blood-brain barrier penetration after systemic administration, with no evidence of meaningful CNS access.",
  "evidence_gaps": [
    "No direct positive CNS-access evidence was retrieved; all molecule-level records support inadequate brain penetration.",
    "Most evidence is from rodent or ex vivo measurements, with limited human CSF or target-engagement data."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

